// partner-invite: one branded invitation e-mail for the Partner Program, sent from the support Gmail.
// The e-mail carries the secure link to create the password (generated by Supabase Auth, not sent by Supabase).
// Called by the admin console (Partners → New partner / Resend invitation) with the admin's session.
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.4";
import nodemailer from "npm:nodemailer@6.9.16";

const SB_URL = Deno.env.get("SUPABASE_URL")!;
const SB_SERVICE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const SB_ANON = Deno.env.get("SUPABASE_ANON_KEY") ?? "";
const SITE = (Deno.env.get("SITE_URL") ?? "https://endeavorbiz.com").replace(/\/$/, "");
const SMTP_USER = Deno.env.get("SMTP_USER") ?? "support@endeavorbiz.com";
const SMTP_PASS = (Deno.env.get("SMTP_PASS") ?? "").replace(/\s+/g, "");
const SMTP_HOST = Deno.env.get("SMTP_HOST") ?? "smtp.gmail.com";
const FROM_NAME = Deno.env.get("SMTP_FROM_NAME") ?? "Endeavor Business Solutions";
const PHONE = "+1 (407) 436-9567";
const db = createClient(SB_URL, SB_SERVICE, { auth: { persistSession: false } });

type Lang = "pt" | "en" | "es";
const CORS = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info", "Access-Control-Allow-Methods": "POST, OPTIONS" };
const json = (b: unknown, s = 200) => new Response(JSON.stringify(b), { status: s, headers: { ...CORS, "Content-Type": "application/json" } });
const esc = (s: unknown) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]!));

